/**
 * R-38's chuỗi ngày học. Read the note on `longest` before rendering it,
 * and note what this object does NOT carry — the list is deliberate and is
 * checked by a test.
 *
 * **No deadline of any kind.** No expiry, no time remaining, no "at risk",
 * no end-of-day timestamp, nothing a countdown could be drawn from
 * (TCCN-606-3). The screen may say a learner has not studied today; it may
 * never say how long they have left.
 *
 * **No restore, no repair, no freeze, no price.** A streak cannot be
 * bought back, traded, or unlocked by watching an advert (TCCN-606-4), so
 * there is no field here for a client to build one of those against — and
 * no endpoint anywhere that can write a day that has passed.
 *
 * **Nothing about losing one.** No `previousStreak`, no `brokenOn`, no
 * `missedDays`. A break is not an event this API reports (TCCN-606-1); a
 * new run simply starts at 1 and is stated as an ordinary number
 * (TCCN-606-2). `longest` is the only backward-looking number here, and it
 * is a record to return to rather than a loss to mourn.
 *
 * **Nothing comparative.** No rank, percentile, average or cohort. The
 * record is the learner's own (TCCN-602-1).
 */
export interface StudyStreak {
  /**
     * Consecutive days up to and including today — or up to yesterday,
     * when today has not counted yet.
     *
     * A run that ended yesterday is still current, and that is not a
     * rounding choice: the learner has the rest of the day to continue it,
     * and reporting 0 the moment they open the app before studying would
     * be the "dấu hiệu sai hỏng" TCCN-606-1 forbids, announced at 9am to
     * somebody who has done nothing wrong.
     *
     * 0 means the last activity was two or more days ago, or there has
     * never been any. The client renders those two the same way, so the
     * screen cannot comment on a break it can no longer see.
     */
  current: number;
  /**
     * The longest run this learner has ever had. Theirs alone; never a
     * cohort figure (TCCN-602-1).
     *
     * **It includes the run in progress**, so on a learner's first ever
     * day this is 1 and not 0 — `"Kỷ lục: 0 ngày"` is unreachable from
     * this API. The client hides the record line when `longest <=
     * current`, which is TCCN-602-2 on day one and is also right on day 7
     * of a 6-day record. Reporting null instead would give this field two
     * meanings, and a field with two meanings gets one of them rendered
     * wrong.
     *
     * It survives gaps. Missing a day ends the current run and starts a
     * new one; it never touches this number (TCCN-606-1).
     */
  longest: number;
  /**
     * Whether today already counts. Needed separately from `current`
     * because "6 ngày liền" and "làm một việc nữa là tròn 7" are different
     * sentences and the number alone cannot tell them apart.
     *
     * False is not a warning. It is the ordinary state of every morning.
     */
  activeToday: boolean;
  /**
     * The most recent day that counted, in `CurrentUser.timezone`. Absent
     * when nothing ever has.
     *
     * A date, never a timestamp, and that line is the one worth holding: a
     * time of day here is the one input a countdown needs.
     */
  lastActiveOn?: string;
}
